ST.xhtml:p:
bCutHeadCoolEnable := g_TechData.multilTechData[g_nToolNum -1].DIRECUT_CUTTING.bCutHeadCoolEnable;
fCutHeadCoolCloseTime := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutHeadCoolCloseTime;
fTrigDot(CLK := (g_bLaserDotEnable));  (*激光打点PWM关闭差周期,所以这里强制关下,不然会导致出冷却气*)
IF fTrigDot.Q THEN
  g_noUPwmDuty := 0;
END_IF;
(*切割头吹气冷却:开光出气,关光延时关闭*)
IF bCutHeadCoolEnable AND Not g_bLaserDotEnable THEN
  Tof_CutHeadCool(IN := (g_noUPwmDuty<>0 OR g_bLaserCuttingEnable),PT := LREAL_TO_TIME(fCutHeadCoolCloseTime)); 
  g_boCutHeadCool :=  Tof_CutHeadCool.Q; 
ELSE
  g_boCutHeadCool := FALSE;
  Tof_CutHeadCool(IN := FALSE,PT := T#0s); 
END_IF;
